def encode_mhc_ii(mhc_a,mhc_b,n):
    contacts_iia=[x for x in pmhc_contacts['II'][:n]['res'].values if x<'1001 ']
    contacts_iib=[x for x in pmhc_contacts['II'][:n]['res'].values if x>='1001 ']
